const has = (key) => Object.prototype.hasOwnProperty.call(UI_AR, key);
// Localize content at display sinks; never call this for action IDs, filenames or key events.
export function translateUI(value) {
  if (typeof window !== "undefined" && window.__tsuki_lang !== "ar") return value;
  if (value === undefined || value === null) return value;
  const text = String(value);
  if (has(text)) return UI_AR[text];
  const trimmed = text.trim();
  if (has(trimmed)) return text.slice(0, text.indexOf(trimmed)) + UI_AR[trimmed] + text.slice(text.indexOf(trimmed) + trimmed.length);
  let match;
  if ((match = /^No\. (\d+)$/.exec(trimmed))) return `رقم ${match[1]}`;
  if ((match = /^CG\s+(\d+)$/i.exec(trimmed))) return `صورة ${match[1]}`;
  if ((match = /^(.+), key (\d+)$/.exec(trimmed))) return `${translateUI(match[1])}، المفتاح ${match[2]}`;
  if ((match = /^Music:\s*(.+)$/.exec(trimmed))) return `الموسيقى: ${translateUI(match[1])}`;
  if ((match = /^(?:Play\s+)?["“]?Teach [Mm]e, Ciel-[Ss]ensei!?\s*(?:Ep\.?\s*)?(\d+)["”]?[?？]?$/.exec(trimmed))) {
    const title = `علّميني أستاذة سِيل! الحلقة ${match[1]}`;
    return /^Play/.test(trimmed) ? `هل تريد تشغيل «${title}»؟` : title;
  }
  if ((match = /^Enter hint corner \(No\. (\d+)\)[?？]$/.exec(trimmed))) return `هل تريد دخول ركن التلميحات رقم ${match[1]}؟`;
  if ((match = /^Could not start:\s*(.*)$/.exec(trimmed))) return `تعذر بدء اللعبة: ${translateUI(match[1])}`;
  if ((match = /^(Loading|Saving)\s+(\d+)%$/.exec(trimmed))) return `${translateUI(match[1])} ${match[2]}٪`;
  if ((match = /^(.+) \(not read yet\)$/.exec(trimmed))) return `${translateUI(match[1])} (لم يُقرأ بعد)`;
  if ((match = /^Tsukihime\.apk, below, on the phone itself\. It is large, so Wi-Fi is best\.$/.exec(trimmed))) return 'نزّل ملف Tsukihime.apk أدناه على الهاتف نفسه. حجمه كبير، لذا يُفضّل اتصال واي فاي.';
  // Joined help labels and key combinations retain separators while translating their human words.
  if (/[,·]|\s\/\s/.test(trimmed)) {
    const parts = text.split(/(\s*[·,]\s*|\s+\/\s+)/);
    let changed = false;
    const translated = parts.map(part => { if (has(part)) { changed = true; return UI_AR[part]; } if (has(part.trim())) { changed = true; return translateUI(part); } return part; });
    if (changed) return translated.join('');
  }
  return text;
}
